// Generated by Codex and not thoroughly checked for correctness.
func TestUserLimitsShareReadsAndApplyAdditionalWriteBudget(t *testing.T) {
	gin.SetMode(gin.TestMode)
	now := time.Now()
	service, err := ratelimit.New(ratelimit.DefaultConfig(), ratelimit.WithClock(func() time.Time { return now }))
	if err != nil {
		t.Fatal(err)
	}
	router := gin.New()
	router.Use(func(ctx *gin.Context) { ctx.Set(middlewares.UserIdKey, int64(42)) }, middlewares.LimitUser(service))
	router.Any("/first", func(ctx *gin.Context) { ctx.Status(http.StatusNoContent) })
	router.Any("/second", func(ctx *gin.Context) { ctx.Status(http.StatusNoContent) })
	for range 10 {
		assertLimitedRequest(t, router, http.MethodPost, "/first", http.StatusNoContent)
	}
	assertLimitedRequest(t, router, http.MethodGet, "/second", http.StatusTooManyRequests)
	now = now.Add(time.Second)
	assertLimitedRequest(t, router, http.MethodDelete, "/second", http.StatusTooManyRequests)
	now = now.Add(time.Second)
	assertLimitedRequest(t, router, http.MethodPatch, "/first", http.StatusNoContent)
	now = now.Add(time.Second)
	assertLimitedRequest(t, router, http.MethodGet, "/second", http.StatusNoContent)
}

// Generated by Codex and not thoroughly checked for correctness.
func TestIPLimitUsesTrustedClientAddressAndSharedAliasBudget(t *testing.T) {
	gin.SetMode(gin.TestMode)
	service, err := ratelimit.New(ratelimit.DefaultConfig())
	if err != nil {
		t.Fatal(err)
	}
	router := gin.New()
	if err := router.SetTrustedProxies(nil); err != nil {
		t.Fatal(err)
	}
	router.Use(middlewares.LimitAuthentication(service))
	router.GET("/login", func(ctx *gin.Context) { ctx.Status(http.StatusNoContent) })
	router.GET("/alias", func(ctx *gin.Context) { ctx.Status(http.StatusNoContent) })
	for index := range 11 {
		response := httptest.NewRecorder()
		request := httptest.NewRequest(http.MethodGet, "/login", nil)
		if index == 10 {
			request.URL.Path = "/alias"
		}
		request.RemoteAddr = "192.0.2.1:1234"
		// Changing a spoofed forwarded address must not reset the allowance.
		request.Header.Set("X-Forwarded-For", "198.51.100."+strconv.Itoa(index+1))
		router.ServeHTTP(response, request)
		want := http.StatusNoContent
		if index == 10 {
			want = http.StatusTooManyRequests
		}
		if response.Code != want {
			t.Fatalf("request %d status=%d, want %d", index, response.Code, want)
		}
	}
}

func assertLimitedRequest(t *testing.T, router *gin.Engine, method, path string, want int) {
	t.Helper()
	response := httptest.NewRecorder()
	router.ServeHTTP(response, httptest.NewRequest(method, path, nil))
	if response.Code != want {
		t.Fatalf("%s %s status=%d, want %d", method, path, response.Code, want)
	}
}
